"""Events and their links to members and documents."""

from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy import select
from sqlalchemy.orm import Session

from app.api.deps import (
    get_current_user,
    get_readable_tree,
    get_writable_tree,
    require_domain,
    require_feature,
)
from app.api.pagination import Pagination, apply_pagination, pagination_params
from app.db.session import get_db
from app.models import Event, EventDocumentLink, EventMemberLink, Tree
from app.models.user import User
from app.schemas.content import (
    DocumentIdsSet,
    EventCreate,
    EventLinkOut,
    EventOut,
    EventUpdate,
    LinksSet,
)
from app.services.activity.activity import event_delete_snapshot, record_activity
from app.services.documents.content_links import (
    replace_document_links,
    replace_member_links,
)
from app.services.event_bus import publish_tree_event
from app.services.media.storage_usage import check_tree_quota
from app.services.unit_of_work import UnitOfWork

router = APIRouter(
    prefix="/trees/{tree_id}/events",
    tags=["events"],
    dependencies=[
        Depends(require_feature("events")),
        Depends(require_domain("events")),
    ],
)


def _get_event(db: Session, tree: Tree, event_id: str) -> Event:
    event = db.get(Event, event_id)
    if event is None or event.tree_id != tree.id:
        raise HTTPException(status_code=404, detail="Event not found")
    return event


def _document_ids(db: Session, event_id: str) -> list[str]:
    return list(
        db.scalars(
            select(EventDocumentLink.document_id).where(
                EventDocumentLink.event_id == event_id
            )
        ).all()
    )


def _event_out(db: Session, event: Event) -> EventOut:
    return EventOut.model_validate(event).model_copy(
        update={"document_ids": _document_ids(db, event.id)}
    )


def _events_out(db: Session, events: list[Event]) -> list[EventOut]:
    if not events:
        return []
    event_ids = [e.id for e in events]
    rows = db.execute(
        select(EventDocumentLink.event_id, EventDocumentLink.document_id).where(
            EventDocumentLink.event_id.in_(event_ids)
        )
    ).all()
    doc_map: dict[str, list[str]] = {}
    for eid, did in rows:
        doc_map.setdefault(eid, []).append(did)
    return [
        EventOut.model_validate(e).model_copy(
            update={"document_ids": doc_map.get(e.id, [])}
        )
        for e in events
    ]


@router.get("", response_model=list[EventOut])
def list_events(
    pagination: Pagination = Depends(pagination_params),
    tree: Tree = Depends(get_readable_tree),
    db: Session = Depends(get_db),
):
    statement = (
        select(Event).where(Event.tree_id == tree.id).order_by(Event.created_at, Event.id)
    )
    events = db.scalars(apply_pagination(statement, pagination)).all()
    return _events_out(db, list(events))


@router.get("/links", response_model=list[EventLinkOut])
def list_links(
    pagination: Pagination = Depends(pagination_params),
    tree: Tree = Depends(get_readable_tree),
    db: Session = Depends(get_db),
):
    statement = (
        select(EventMemberLink)
        .join(Event, Event.id == EventMemberLink.event_id)
        .where(Event.tree_id == tree.id)
        .order_by(EventMemberLink.event_id, EventMemberLink.member_id)
    )
    return db.scalars(apply_pagination(statement, pagination)).all()


@router.post("", response_model=EventOut, status_code=201)
def create_event(
    payload: EventCreate,
    tree: Tree = Depends(get_writable_tree),
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    data = payload.model_dump()
    member_ids = data.pop("member_ids")
    check_tree_quota(db, tree, len(str(data).encode()))
    with UnitOfWork(db) as uow:
        event = Event(tree_id=tree.id, **data)
        db.add(event)
        db.flush()  # event row must exist before its links reference it
        replace_member_links(
            db,
            link_model=EventMemberLink,
            parent_fk=EventMemberLink.event_id,
            parent_id=event.id,
            tree=tree,
            member_ids=member_ids,
        )
        record_activity(
            db, tree_id=tree.id, actor=user, action="create",
            target_type="event", target_id=event.id, target_label=event.event_type,
        )
        uow.after_commit(
            lambda: publish_tree_event(
                db, tree, "activity.entry_added", {"tree_id": tree.id}
            )
        )
        uow.after_commit(
            lambda: publish_tree_event(
                db, tree, "tree.content_changed", {"tree_id": tree.id, "domain": "event"}
            )
        )
    db.refresh(event)
    return _event_out(db, event)


@router.patch("/{event_id}", response_model=EventOut)
def update_event(
    event_id: str,
    payload: EventUpdate,
    tree: Tree = Depends(get_writable_tree),
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    event = _get_event(db, tree, event_id)
    with UnitOfWork(db) as uow:
        for key, value in payload.model_dump().items():
            setattr(event, key, value)
        record_activity(
            db, tree_id=tree.id, actor=user, action="update",
            target_type="event", target_id=event.id, target_label=event.event_type,
        )
        uow.after_commit(
            lambda: publish_tree_event(
                db, tree, "activity.entry_added", {"tree_id": tree.id}
            )
        )
        uow.after_commit(
            lambda: publish_tree_event(
                db, tree, "tree.content_changed", {"tree_id": tree.id, "domain": "event"}
            )
        )
    db.refresh(event)
    return _event_out(db, event)


@router.delete("/{event_id}", status_code=204)
def delete_event(
    event_id: str,
    tree: Tree = Depends(get_writable_tree),
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    event = _get_event(db, tree, event_id)
    with UnitOfWork(db) as uow:
        record_activity(
            db, tree_id=tree.id, actor=user, action="delete",
            target_type="event", target_id=event.id, target_label=event.event_type,
            details=event_delete_snapshot(db, event),
        )
        db.delete(event)
        uow.after_commit(
            lambda: publish_tree_event(
                db, tree, "activity.entry_added", {"tree_id": tree.id}
            )
        )
        uow.after_commit(
            lambda: publish_tree_event(
                db, tree, "tree.content_changed", {"tree_id": tree.id, "domain": "event"}
            )
        )


@router.put("/{event_id}/links", status_code=204)
def set_links(
    event_id: str,
    payload: LinksSet,
    tree: Tree = Depends(get_writable_tree),
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    """Replace the full set of members linked to this event."""
    event = _get_event(db, tree, event_id)
    with UnitOfWork(db) as uow:
        replace_member_links(
            db,
            link_model=EventMemberLink,
            parent_fk=EventMemberLink.event_id,
            parent_id=event_id,
            tree=tree,
            member_ids=payload.member_ids,
        )
        record_activity(
            db, tree_id=tree.id, actor=user, action="update",
            target_type="event", target_id=event.id, target_label=event.event_type,
        )
        uow.after_commit(
            lambda: publish_tree_event(
                db, tree, "activity.entry_added", {"tree_id": tree.id}
            )
        )
        uow.after_commit(
            lambda: publish_tree_event(
                db, tree, "tree.content_changed", {"tree_id": tree.id, "domain": "event"}
            )
        )


@router.put("/{event_id}/documents", status_code=204)
def set_documents(
    event_id: str,
    payload: DocumentIdsSet,
    tree: Tree = Depends(get_writable_tree),
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    """Replace the full set of documents linked to this event."""
    event = _get_event(db, tree, event_id)
    with UnitOfWork(db) as uow:
        replace_document_links(
            db,
            link_model=EventDocumentLink,
            parent_fk=EventDocumentLink.event_id,
            parent_id=event_id,
            tree=tree,
            document_ids=payload.document_ids,
        )
        record_activity(
            db, tree_id=tree.id, actor=user, action="update",
            target_type="event", target_id=event.id, target_label=event.event_type,
        )
        uow.after_commit(
            lambda: publish_tree_event(
                db, tree, "activity.entry_added", {"tree_id": tree.id}
            )
        )
        uow.after_commit(
            lambda: publish_tree_event(
                db, tree, "tree.content_changed", {"tree_id": tree.id, "domain": "event"}
            )
        )

"""Source-list validation and persistence for virtual-view configuration.

A view's ``source_tree_ids`` payload (from create/update) is a flat list of
real tree ids and/or nested ``vv_`` view ids. This module turns that untrusted
list into a validated, ordered ``[(kind, id), ...]`` — enforcing the ≥2
distinct sources rule, recursive read access to every underlying real tree,
and cycle rejection — and persists it as ``VirtualViewSource`` rows.
"""

from __future__ import annotations

from fastapi import HTTPException
from sqlalchemy.orm import Session

from app.api.deps import accessible_tree_ids
from app.models import User
from app.models.virtual_view import VirtualView, VirtualViewSource
from app.services.virtual_views.virtual_view_sources import flatten_tree_ids, view_closure

VIRTUAL_VIEW_SOURCE_CYCLE = "virtual_view_source_cycle"


def classify_and_validate_sources(
    db: Session,
    user: User,
    source_ids: list[str],
    target_view_id: str | None,
) -> list[tuple[str, str]]:
    """Validate a proposed source list; return ``[(kind, id), ...]`` in order.

    Accepts real tree ids and ``vv_`` view ids. Enforces the ≥2 distinct sources
    rule, recursive read access to every underlying real tree, and rejects
    cycles (``target_view_id`` may not appear in any source view's closure).
    Raises ``HTTPException`` on any problem.
    """
    unique_ids = list(dict.fromkeys(source_ids))
    if len(unique_ids) < 2:
        raise HTTPException(
            status_code=400, detail="At least 2 distinct source trees required"
        )
    accessible = set(accessible_tree_ids(db, user))
    resolved: list[tuple[str, str]] = []
    for sid in unique_ids:
        if sid.startswith("vv_"):
            nested = db.get(VirtualView, sid)
            if nested is None or (
                nested.owner_id != user.id and not user.is_admin
            ):
                raise HTTPException(
                    status_code=403, detail=f"No access to view {sid}"
                )
            if target_view_id is not None and target_view_id in view_closure(
                db, sid
            ):
                raise HTTPException(
                    status_code=409, detail=VIRTUAL_VIEW_SOURCE_CYCLE
                )
            for tid in flatten_tree_ids(db, nested):
                if tid not in accessible:
                    raise HTTPException(
                        status_code=403, detail=f"No access to tree {tid}"
                    )
            resolved.append(("view", sid))
        else:
            if sid not in accessible:
                raise HTTPException(
                    status_code=403, detail=f"No access to tree {sid}"
                )
            resolved.append(("tree", sid))
    return resolved


def flatten_resolved(db: Session, resolved: list[tuple[str, str]]) -> list[str]:
    """Ordered, de-duplicated real tree ids for a validated source list."""
    flat: list[str] = []
    for kind, sid in resolved:
        if kind == "tree":
            if sid not in flat:
                flat.append(sid)
        else:
            nested = db.get(VirtualView, sid)
            if nested is None:
                continue
            for tid in flatten_tree_ids(db, nested):
                if tid not in flat:
                    flat.append(tid)
    return flat


def persist_sources(
    db: Session, view: VirtualView, resolved: list[tuple[str, str]]
) -> None:
    """Replace a view's source rows from a validated ``[(kind, id)]`` list."""
    for i, (kind, sid) in enumerate(resolved):
        if kind == "tree":
            db.add(VirtualViewSource(view_id=view.id, position=i, tree_id=sid))
        else:
            db.add(
                VirtualViewSource(
                    view_id=view.id, position=i, source_view_id=sid
                )
            )

