    except GeocodeUnavailableError:
        # Not cached: the next call retries immediately. A stale unresolved
        # row (if any) is left untouched and stays retryable.
        pass
    else:
        if result:
            lat, lon, display_name = result
            row = GeocodeCache(
                query=query, lat=lat, lon=lon,
